SYN03_agentic_grep_14ab1e66.final_sparql:
PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?activity ?activityLabel ?exchange ?exchangeLabel ?direction ?exchangeType
WHERE {
  {
    ?exchange a oriont:ProductFlow ;
              rdfs:label ?exchangeLabel ;
              oriont:isInputOf ?activity .
    ?activity a oriont:Activity ;
              rdfs:label ?activityLabel .
    BIND("input" AS ?direction)
    BIND("ProductFlow" AS ?exchangeType)
  }
  UNION
  {
    ?exchange a oriont:ProductFlow ;
              rdfs:label ?exchangeLabel ;
              oriont:isOutputOf ?activity .
    ?activity a oriont:Activity ;
              rdfs:label ?activityLabel .
    BIND("output" AS ?direction)
    BIND("ProductFlow" AS ?exchangeType)
  }
  UNION
  {
    ?exchange a oriont:ElementaryFlow ;
              rdfs:label ?exchangeLabel ;
              oriont:isInputOf ?activity .
    ?activity a oriont:Activity ;
              rdfs:label ?activityLabel .
    BIND("input" AS ?direction)
    BIND("ElementaryFlow" AS ?exchangeType)
  }
  UNION
  {
    ?exchange a oriont:ElementaryFlow ;
              rdfs:label ?exchangeLabel ;
              oriont:isOutputOf ?activity .
    ?activity a oriont:Activity ;
              rdfs:label ?activityLabel .
    BIND("output" AS ?direction)
    BIND("ElementaryFlow" AS ?exchangeType)
  }
}
ORDER BY ?activityLabel ?direction ?exchangeLabel

SYN03_agentic_grep_14ab1e66.gt_sparql:
